from __future__ import annotations

import os
from datetime import datetime
from typing import TYPE_CHECKING

from buvis.pybase.result import FatalError

from backup.capabilities import CAPABILITIES
from backup.config import effective_excludes
from backup.step_result import PlanEntry, StepResult

if TYPE_CHECKING:
    from collections.abc import Iterator

    from backup.config import BackupConfig, BackupInstance

__all__ = ["Runner"]


class Runner:
    """Execute selected backup instances, yielding a :class:`StepResult` per step.

    Each instance invokes its registered capability with the instance's ``with:``
    inputs plus the runtime context the capability needs: the resolved instance
    ``excludes`` list, the instance ``label``, and the ``dry_run`` flag. Under
    ``dry_run`` the capability itself previews (walks + reports) without writing.
    """

    def __init__(self: Runner, cfg: BackupConfig, *, dry_run: bool = False) -> None:
        self._cfg = cfg
        self._dry_run = dry_run

    def run(self: Runner, selected: list[tuple[str, BackupInstance]]) -> Iterator[StepResult]:
        now = datetime.now()
        entries = self._plan(selected, now)
        for (name, instance), entry in zip(selected, entries, strict=True):
            if entry.status == "fail":
                yield StepResult(name, success=False, message=entry.reason)
            else:
                yield from self._run_instance(name, instance, now)

    def plan(self: Runner, selected: list[tuple[str, BackupInstance]]) -> list[PlanEntry]:
        return self._plan(selected, datetime.now())

    def _plan(self: Runner, selected: list[tuple[str, BackupInstance]], now: datetime) -> list[PlanEntry]:
        entries = []
        outputs: dict[str, list[str]] = {}
        for name, instance in selected:
            capability = CAPABILITIES.get(instance.use)
            if capability is None:  # pragma: no cover - load_config validates this
                entry = PlanEntry(name, "", "", "fail", f"unknown capability '{instance.use}'", False)
            else:
                call_kwargs: dict[str, object] = {
                    **instance.with_,
                    "label": name,
                    "excludes": list(effective_excludes(self._cfg, instance)),
                    "now": now,
                }
                entry = capability.plan(**call_kwargs)
            entries.append(entry)
            if capability is None:
                continue
            out = os.path.normpath(os.path.expanduser(entry.out))
            outputs.setdefault(out, []).append(name)

        for index, entry in enumerate(entries):
            out = os.path.normpath(os.path.expanduser(entry.out))
            names = outputs.get(out, [])
            if len(names) > 1:
                others = ", ".join(sorted(name for name in names if name != entry.label))
                entries[index] = entry._replace(
                    out=out,
                    status="fail",
                    reason=f"output '{out}' is also the output of '{others}'",
                )
        return entries

    def _run_instance(self: Runner, name: str, instance: BackupInstance, now: datetime) -> Iterator[StepResult]:
        capability = CAPABILITIES[instance.use]

        call_kwargs: dict[str, object] = {
            **instance.with_,
            "label": name,
            "excludes": list(effective_excludes(self._cfg, instance)),
            "dry_run": self._dry_run,
            "now": now,
        }
        try:
            yield from capability.run(**call_kwargs)
        except FatalError:
            raise
        except Exception as exc:
            yield StepResult(name, success=False, message=f"{name} failed: {exc}")

from __future__ import annotations

from typing import TYPE_CHECKING

import click
from buvis.pybase.adapters import console
from buvis.pybase.configuration import buvis_options
from buvis.pybase.result import FatalError

from backup.settings import BackupSettings

if TYPE_CHECKING:
    from collections.abc import Iterable

    from backup.config import BackupConfig, BackupInstance
    from backup.step_result import StepResult


def _report_step(step: StepResult) -> None:
    if step.skipped:
        console.warning(step.message or f"{step.label} skipped")
    elif step.success:
        console.success(step.message or f"{step.label} archived")
    else:
        console.failure(step.message or f"{step.label} failed")


def _report_steps(steps: Iterable[StepResult], *, dry_run: bool = False) -> bool:
    """Render every step (success and failure) and report whether any failed.

    All steps are rendered before the caller acts on the return, so the user
    sees every failure — the CLI must not stop at the first one. Returns ``True``
    when at least one step failed, so the CLI layer can exit nonzero (a cron job
    treating an incomplete backup as success is the bug this closes).
    """
    archived = skipped = failed = 0
    for step in steps:
        _report_step(step)
        if not step.success:
            failed += 1
        elif step.skipped:
            skipped += 1
        else:
            archived += 1
    verb = "previewed" if dry_run else "archived"
    console.info(f"{verb} {archived}, skipped {skipped}, failed {failed}")
    return failed > 0


def _parse_only(only: tuple[str, ...]) -> set[str]:
    names: set[str] = set()
    for item in only:
        names.update(part.strip() for part in item.split(",") if part.strip())
    return names


def _describe(name: str, instance: BackupInstance) -> str:
    tags = f" [tags: {', '.join(instance.tags)}]" if instance.tags else ""
    return f"{instance.order:>4}  {name}  (use:{instance.use}){tags}"


def _apply_overrides(instance: BackupInstance, source: str, out: str) -> BackupInstance:
    """Return a copy of ``instance`` with ``source`` / ``out`` overridden in ``with_``.

    A non-empty flag value replaces the instance's configured value for a
    one-shot run; an empty value leaves the config value untouched (flag wins
    over config). The frozen model is copied rather than mutated.
    """
    merged = dict(instance.with_)
    if source:
        merged["source"] = source
    if out:
        merged["out"] = out
    return instance.model_copy(update={"with_": merged})


def _override_selected(
    plan: list[tuple[str, BackupInstance]], source: str, out: str
) -> list[tuple[str, BackupInstance]]:
    if not (source or out):
        return plan
    if len(plan) != 1:
        console.failure(
            f"--source/--out require exactly one selected instance (via --only); {len(plan)} selected",
        )
        raise SystemExit(1)
    name, instance = plan[0]
    return [(name, _apply_overrides(instance, source, out))]


def _list_instances(plan: list[tuple[str, BackupInstance]]) -> None:
    if not plan:
        console.info("no configured instances")
    else:
        for name, instance in plan:
            console.info(_describe(name, instance))


def _load_config(ctx: click.Context) -> BackupConfig | None:
    from backup.config import load_config

    # Honour the same --config / --config-dir the buvis_options wrapper resolved
    # settings from, so the backup PLAN and BackupSettings come from ONE source.
    # The wrapper publishes the raw selection on ctx.obj (None when unset); pass
    # it through so `backup --config FILE` runs the plan from FILE and
    # `--config-dir DIR` discovers it under DIR. (PRD 00084 closed the split that
    # was deferred from PR #179.)
    obj = ctx.obj or {}
    config_dir = obj.get("config_dir")
    config_path = obj.get("config_path")
    try:
        return load_config(config_dir=config_dir, config_path=config_path)
    except FatalError as exc:
        console.panic(str(exc))
        return None


def _show_excludes(cfg: BackupConfig, instance_name: str, for_path: str) -> bool:
    """Print the resolved exclude set for ``instance_name`` under ``--for`` path.

    Renders the instance exclude set (after inheritance, removals and additions)
    and, when ``for_path`` is given, the ``.bkpignore`` add / ``!``-unignore
    rules effective under that path — resolved with the same layering the
    archive walk uses. Writes no archive. Without ``--for`` prints the instance
    set only and notes that path-dependent ``.bkpignore`` rules are omitted.

    Returns ``True`` on a terminal validation failure (unknown instance, or an
    instance with no source) so the CLI layer can exit nonzero — a typo like
    ``backup --show-excludes typo`` must not look like a successful inspection
    to a script.
    """
    from pathlib import Path

    from backup.config import effective_excludes
    from backup.shared.bkpignore import ExcludeState, resolve_state_for_path

    instance = cfg.instances.get(instance_name)
    if instance is None:
        console.failure(f"unknown instance '{instance_name}'")
        return True

    excludes = effective_excludes(cfg, instance)
    console.info(f"resolved excludes for '{instance_name}':")
    for pattern in excludes:
        console.info(f"  {pattern}")

    if not for_path:
        console.info("(.bkpignore rules omitted — path-dependent; pass --for <path> to resolve them)")
        return False

    source_raw = instance.with_.get("source")
    if not isinstance(source_raw, str) or not source_raw:
        console.failure(f"instance '{instance_name}' has no source configured")
        return True

    source = Path(source_raw).expanduser()
    target = Path(for_path).expanduser()
    base_state = ExcludeState(base_excludes=frozenset(excludes))
    state = resolve_state_for_path(source, base_state, target)

    console.info(f".bkpignore rules effective under {target}:")
    if state.applied:
        for rule in state.applied:
            console.info(f"  {rule}")
    else:
        console.info("  none")
    return False


def _select_plan(
    cfg: BackupConfig,
    plan: list[tuple[str, BackupInstance]],
    only: tuple[str, ...],
    tags: tuple[str, ...],
) -> tuple[list[tuple[str, BackupInstance]], bool]:
    """Narrow ``plan`` by ``--only`` names and ``--tag`` tags, reporting skips via console.

    Returns the narrowed plan plus a flag that is ``True`` when any requested
    ``--only`` name was unknown to the config. Valid names still run (the caller
    executes whatever survived), but the flag lets the CLI exit nonzero so a typo
    that leaves an empty or reduced plan cannot make a scheduled backup silently
    do nothing (or less) while reporting success.
    """
    had_unknown = False
    only_names = _parse_only(only)
    if only_names:
        selected_names = {name for name, _ in plan}
        for requested in sorted(only_names):
            if requested not in cfg.instances:
                console.failure(f"unknown instance '{requested}', skipping")
                had_unknown = True
            elif requested not in selected_names:
                console.info(f"'{requested}' is disabled, skipping")
        plan = [(name, instance) for name, instance in plan if name in only_names]

    if tags:
        wanted = set(tags)
        plan = [(name, instance) for name, instance in plan if wanted & set(instance.tags)]

    return plan, had_unknown


def _run_plan(cfg: BackupConfig, plan: list[tuple[str, BackupInstance]], *, dry_run: bool, plan_only: bool) -> bool:
    """Run the selected plan, rendering every step; return whether any failed.

    Rendering all steps before returning means the user sees every failure (the
    CLI must not stop at the first). Returns ``True`` if any step failed so the
    caller can exit nonzero — a cron job treating an incomplete backup as success
    is the bug this closes. A ``FatalError`` from the runner is surfaced via
    ``console.panic`` (which exits).
    """
    from backup.runner import Runner

    try:
        runner = Runner(cfg, dry_run=dry_run)
        if plan_only:
            entries = runner.plan(plan)
            for entry in entries:
                message = f"{entry.label}  {entry.status}  {entry.source} -> {entry.out}"
                if entry.reason:
                    message += f"  ({entry.reason})"
                if entry.replaces:
                    message += "  [replaces existing]"
                console.info(message)
            return any(entry.status == "fail" for entry in entries)
        return _report_steps(runner.run(plan), dry_run=dry_run)
    except FatalError as exc:
        console.panic(str(exc))
        return True  # unreachable: panic exits, but keeps the type honest


@click.command(help="Run configured backup archives")
@click.option("--only", multiple=True, help="Run only these instance names (comma-separated or repeated).")
@click.option("--tag", "tags", multiple=True, help="Run only instances carrying one of these tags.")
@click.option("--list", "list_plan", is_flag=True, help="Print the configured instances and exit.")
@click.option("--plan", "plan_only", is_flag=True, help="Print the selected archive plan without walking sources.")
@click.option("--dry-run", is_flag=True, help="Walk and report what would be archived without writing it.")
@click.option("--source", default="", help="Override the single selected instance's source for this run.")
@click.option("--out", default="", help="Override the single selected instance's out path for this run.")
@click.option(
    "--show-excludes",
    "show_excludes",
    default="",
    help="Print an instance's resolved exclude set and exit (read-only).",
)
@click.option("--for", "for_path", default="", help="Resolve .bkpignore rules under this path for --show-excludes.")
@buvis_options(settings_class=BackupSettings)
@click.pass_context
def cli(  # noqa: PLR0917  # Click binds one callback arg per CLI option
    ctx: click.Context,
    only: tuple[str, ...],
    tags: tuple[str, ...],
    list_plan: bool,
    plan_only: bool,
    dry_run: bool,
    source: str,
    out: str,
    show_excludes: str,
    for_path: str,
) -> None:
    from backup.config import applicable_instances

    if plan_only and dry_run:
        console.failure("--plan and --dry-run are mutually exclusive")
        raise SystemExit(1)

    # --for only qualifies --show-excludes' read-only inspection; supplied alone
    # it used to be silently ignored while a real backup RAN. Reject it up front.
    if for_path and not show_excludes:
        console.failure("--for requires --show-excludes")
        raise SystemExit(1)

    cfg = _load_config(ctx)
    if cfg is None:
        return

    if show_excludes:
        failed = _show_excludes(cfg, show_excludes, for_path)
        if failed:
            raise SystemExit(1)
        return

    plan = applicable_instances(cfg)
    plan, unknown_only = _select_plan(cfg, plan, only, tags)

    if list_plan:
        _list_instances(plan)
        if unknown_only:
            raise SystemExit(1)
        return

    plan = _override_selected(plan, source, out)
    any_failed = _run_plan(cfg, plan, dry_run=dry_run, plan_only=plan_only)
    # An unknown --only name (typo) must also fail the run, so a scheduled
    # backup can't silently do nothing (or less) after a mistyped selector.
    if any_failed or unknown_only:
        raise SystemExit(1)


if __name__ == "__main__":
    cli()

from __future__ import annotations

import tarfile
from datetime import datetime
from typing import TYPE_CHECKING

import pytest
from buvis.pybase.result import FatalError

from backup.capabilities.tar_archive import TarArchive
from backup.config import BackupConfig
from backup.runner import Runner
from backup.step_result import PlanEntry

if TYPE_CHECKING:
    from pathlib import Path

    from pytest_mock import MockerFixture


def _config(tmp_path: Path, outputs: dict[str, str]) -> BackupConfig:
    instances = {}
    for name, out in outputs.items():
        source = tmp_path / "sources" / name
        source.mkdir(parents=True)
        (source / "tiny.txt").write_bytes(name.encode())
        instances[name] = {"use": "tar-archive", "with": {"source": str(source), "out": out}}
    return BackupConfig.model_validate({"instances": instances})


def _assert_archive(out: Path, name: str) -> None:
    with tarfile.open(out, "r:gz") as archive:
        assert {member.name for member in archive.getmembers() if member.isfile()} == {f"{name}/tiny.txt"}
        member = archive.extractfile(f"{name}/tiny.txt")
        assert member is not None
        assert member.read() == name.encode()


def _record_archive_creation(monkeypatch: pytest.MonkeyPatch) -> list[tarfile.TarFile]:
    opened = []
    real_open = tarfile.open

    def record_open(*args: object, **kwargs: object) -> tarfile.TarFile:
        archive = real_open(*args, **kwargs)
        opened.append(archive)
        return archive

    monkeypatch.setattr(tarfile, "open", record_open)
    return opened


@pytest.mark.parametrize("mode", ["run", "dry-run", "plan"])
def test_runner_duplicate_groups_reject_all_members_and_keep_independent_outputs(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, mode: str
) -> None:
    shared = tmp_path / "shared.tar.gz"
    second = tmp_path / "second.tar.gz"
    shared.write_bytes(b"keep first group")
    second.write_bytes(b"keep second group")
    groups = {str(shared): ["zinc", "alpha", "beta", "gamma"], str(second): ["omega", "delta"]}
    outputs = {name: out for out, names in groups.items() for name in names}
    independent = {
        "shared-copy": str(tmp_path / "shared.tar.gz.copy"),
        "prefix-shared": str(tmp_path / "prefix-shared.tar.gz"),
        "other-directory": str(tmp_path / "nested" / "shared.tar.gz"),
    }
    outputs.update(independent)
    cfg = _config(tmp_path, outputs)
    missing = tmp_path / "sources" / "gamma"
    (missing / "tiny.txt").unlink()
    missing.rmdir()
    runner = Runner(cfg, dry_run=mode == "dry-run")
    opened = _record_archive_creation(monkeypatch)
    selected = list(cfg.instances.items())
    results = runner.plan(selected) if mode == "plan" else list(runner.run(selected))
    created = [[member.name for member in archive.members if member.isfile()] for archive in opened]
    assert len(results) == len(outputs)
    assert [result.label for result in results] == list(outputs)
    assert created == ([[f"{name}/tiny.txt"] for name in independent] if mode == "run" else [])
    for result in results:
        if result.label in independent:
            assert result.status == "run" if mode == "plan" else result.success is True
            out = tmp_path / independent[result.label]
            assert out.exists() is (mode == "run")
            if mode == "run":
                _assert_archive(out, result.label)
            continue
        out = outputs[result.label]
        others = ", ".join(sorted(name for name in groups[out] if name != result.label))
        message = f"output '{out}' is also the output of '{others}'"
        if mode == "plan":
            assert result == PlanEntry(
                result.label, str(tmp_path / "sources" / result.label), out, "fail", message, True
            )
        else:
            assert result.success is False
            assert result.message == message
    assert shared.read_bytes() == b"keep first group"
    assert second.read_bytes() == b"keep second group"
    assert (tmp_path / "nested").exists() is (mode == "run")


@pytest.mark.parametrize("mode", ["run", "dry-run", "plan"])
@pytest.mark.parametrize("filename", ["daily.tar.gz", "monthly.tgz"])
def test_runner_duplicate_comparison_expands_home_and_normalizes_components(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, mode: str, filename: str
) -> None:
    home = tmp_path / "home"
    home.mkdir()
    monkeypatch.setenv("HOME", str(home))
    out = home / filename
    out.write_bytes(b"keep normalized collision")
    outputs = {"tilde": f"~/{filename}", "normalized": f"{home}/unused/../{filename}"}
    outputs["near-match"] = str(home / "other" / filename)
    cfg = _config(tmp_path, outputs)
    runner = Runner(cfg, dry_run=mode == "dry-run")

    selected = list(cfg.instances.items())
    results = runner.plan(selected) if mode == "plan" else list(runner.run(selected))

    assert len(results) == 3
    assert {result.label for result in results} == set(outputs)
    for result in results:
        if result.label == "near-match":
            assert result.status == "run" if mode == "plan" else result.success is True
            continue
        other = "normalized" if result.label == "tilde" else "tilde"
        message = f"output '{out}' is also the output of '{other}'"
        if mode == "plan":
            assert result.status == "fail"
            assert result.reason == message
        else:
            assert result.success is False
            assert result.message == message
    assert out.read_bytes() == b"keep normalized collision"
    independent = home / "other" / filename
    assert independent.exists() is (mode == "run")
    assert independent.parent.exists() is (mode == "run")
    if mode == "run":
        _assert_archive(independent, "near-match")


@pytest.mark.parametrize("mode", ["run", "dry-run", "plan"])
@pytest.mark.parametrize("now", [datetime(2026, 12, 31, 23, 59, 59), datetime(2027, 1, 1, 0, 0, 1)])
def test_runner_duplicate_guard_compares_timestamp_expanded_outputs(
    tmp_path: Path, mocker: MockerFixture, mode: str, now: datetime
) -> None:
    filename = now.strftime("archive-%Y%m%d-%H%M%S.tar.gz")
    out = tmp_path / filename
    outputs = {"stamped": str(tmp_path / "archive-%Y%m%d-%H%M%S.tar.gz"), "literal": str(out)}
    cfg = _config(tmp_path, outputs)
    clock = mocker.patch("backup.runner.datetime", autospec=True)
    clock.now.return_value = now
    fallback = mocker.patch("backup.capabilities.tar_archive.datetime", autospec=True)
    fallback.now.return_value = datetime(2001, 6, 7, 8, 9, 10)
    runner = Runner(cfg, dry_run=mode == "dry-run")
    selected = list(cfg.instances.items())

    results = runner.plan(selected) if mode == "plan" else list(runner.run(selected))

    assert len(results) == 2
    assert {result.label for result in results} == {"stamped", "literal"}
    for result in results:
        other = "literal" if result.label == "stamped" else "stamped"
        message = f"output '{out}' is also the output of '{other}'"
        if mode == "plan":
            assert result.status == "fail"
            assert result.reason == message
            assert result.out == str(out)
        else:
            assert result.success is False
            assert result.message == message
    assert list(tmp_path.glob("*.tar.gz")) == []


@pytest.mark.parametrize("mode", ["run", "dry-run", "plan"])
def test_runner_duplicate_guard_considers_only_selected_instances(tmp_path: Path, mode: str) -> None:
    outputs = {"chosen": str(tmp_path / "shared.tar.gz"), "unchosen": str(tmp_path / "shared.tar.gz")}
    outputs["chosen-copy"] = str(tmp_path / "shared-copy.tar.gz")
    cfg = _config(tmp_path, outputs)
    selected = [(name, cfg.instances[name]) for name in ("chosen", "chosen-copy")]
    runner = Runner(cfg, dry_run=mode == "dry-run")

    results = runner.plan(selected) if mode == "plan" else list(runner.run(selected))

    assert len(results) == 2
    assert {result.label for result in results} == {"chosen", "chosen-copy"}
    for result in results:
        assert result.status == "run" if mode == "plan" else result.success is True
        out = tmp_path / outputs[result.label]
        assert out.exists() is (mode == "run")
        if mode == "run":
            _assert_archive(out, result.label)


@pytest.mark.parametrize("mode", ["run", "dry-run", "plan"])
def test_runner_empty_selection_returns_no_steps_and_creates_no_output(tmp_path: Path, mode: str) -> None:
    out = tmp_path / "unselected.tar.gz"
    cfg = _config(tmp_path, {"unselected": str(out)})
    runner = Runner(cfg, dry_run=mode == "dry-run")

    results = runner.plan([]) if mode == "plan" else list(runner.run([]))

    assert results == []
    assert not out.exists()
    assert (tmp_path / "sources" / "unselected" / "tiny.txt").read_bytes() == b"unselected"


@pytest.mark.parametrize("modes", [("run", "plan", "run"), ("plan", "run", "plan")])
@pytest.mark.parametrize("dry_run", [False, True])
def test_runner_shares_one_clock_per_call_and_refreshes_between_run_and_plan(
    tmp_path: Path, mocker: MockerFixture, modes: tuple[str, ...], dry_run: bool
) -> None:
    names = ("notes", "photos")
    pattern = "%Y%m%d-%H%M%S-literal-%%Y.tgz"
    cfg = _config(tmp_path, {name: str(tmp_path / f"{name}-{pattern}") for name in names})
    ticks = [
        datetime(2026, 12, 31, 23, 59, 59),
        datetime(2027, 1, 1, 0, 0, 1),
        datetime(2028, 2, 29, 3, 4, 5),
    ]
    clock = mocker.patch("backup.runner.datetime", autospec=True)
    clock.now.side_effect = ticks
    fallback = mocker.patch("backup.capabilities.tar_archive.datetime", autospec=True)
    fallback.now.return_value = datetime(2001, 6, 7, 8, 9, 10)
    runner = Runner(cfg, dry_run=dry_run)
    written = set()

    for mode, now in zip(modes, ticks, strict=True):
        selected = list(cfg.instances.items())
        results = runner.plan(selected) if mode == "plan" else list(runner.run(selected))
        assert len(results) == 2
        assert {result.label for result in results} == set(names)
        for result in results:
            out = tmp_path / f"{result.label}-{now.strftime(pattern)}"
            if mode == "plan":
                expected = TarArchive().plan(label=result.label, now=now, **cfg.instances[result.label].with_)
                assert result == PlanEntry(
                    result.label, str(tmp_path / "sources" / result.label), str(out), "run", expected.reason, False
                )
            else:
                assert result.success is True
                assert result.out_path == str(out)
            assert out.exists() is (mode == "run" and not dry_run)
            if mode == "run" and not dry_run:
                _assert_archive(out, result.label)
                written.add(out)
    assert set(tmp_path.glob("*.tgz")) == written


@pytest.mark.parametrize("mode", ["run", "plan"])
@pytest.mark.parametrize(
    ("invalid", "message"),
    [
        ({"engine": "copy-system-tar"}, "unknown engine 'copy-system-tar'"),
        ({"engine": "python-tarfile-copy"}, "unknown engine 'python-tarfile-copy'"),
    ],
)
def test_runner_preserves_capability_inputs_and_surfaces_validation_failures(
    tmp_path: Path, mode: str, invalid: dict[str, object], message: str
) -> None:
    outputs = {name: str(tmp_path / f"{name}.tar.gz") for name in ("notes", "notes-copy", "invalid")}
    cfg = _config(tmp_path, outputs)
    cfg.instances["invalid"].with_.update(invalid)
    runner = Runner(cfg)

    selected = list(cfg.instances.items())
    results = runner.plan(selected) if mode == "plan" else list(runner.run(selected))

    assert len(results) == 3
    assert {result.label for result in results} == set(outputs)
    for result in results:
        out = tmp_path / outputs[result.label]
        if result.label == "invalid":
            assert result.status == "fail" if mode == "plan" else result.success is False
            assert message in (result.reason if mode == "plan" else result.message)
            assert not out.exists()
            continue
        if mode == "plan":
            expected = TarArchive().plan(label=result.label, **cfg.instances[result.label].with_)
            assert result == PlanEntry(
                result.label, str(tmp_path / "sources" / result.label), str(out), "run", expected.reason, False
            )
        else:
            assert result.success is True
            assert result.out_path == str(out)
            _assert_archive(out, result.label)
        assert out.exists() is (mode == "run")


@pytest.mark.parametrize("inherit", [False, True])
def test_runner_preserves_global_and_instance_exclusion_rules(tmp_path: Path, inherit: bool) -> None:
    names = ("notes", "photos")
    outputs = {name: str(tmp_path / f"{name}.tar.gz") for name in names}
    _config(tmp_path, outputs)
    instances = {
        name: {
            "use": "tar-archive",
            "inherit_excludes": inherit,
            "exclude_remove": ["restored"],
            "exclude_add": ["local-drop"],
            "with": {"source": str(tmp_path / "sources" / name), "out": out},
        }
        for name, out in outputs.items()
    }
    cfg = BackupConfig.model_validate({"instances": instances, "excludes": ["global-drop", "restored"]})
    folders = ("global-drop", "restored", "local-drop", "global-drop-copy", "local-drop-copy")
    for name in names:
        for folder in folders:
            path = tmp_path / "sources" / name / folder / "data.txt"
            path.parent.mkdir()
            path.write_bytes(f"{name}/{folder}".encode())

    results = list(Runner(cfg).run(list(cfg.instances.items())))

    assert [result.label for result in results] == list(names)
    kept = {"restored", "global-drop-copy", "local-drop-copy"}
    if not inherit:
        kept.add("global-drop")
    for result in results:
        assert result.success is True
        with tarfile.open(outputs[result.label], "r:gz") as archive:
            expected = {f"{result.label}/{folder}/data.txt" for folder in kept} | {f"{result.label}/tiny.txt"}
            assert {member.name for member in archive.getmembers() if member.isfile()} == expected
            for folder in kept:
                member = archive.extractfile(f"{result.label}/{folder}/data.txt")
                assert member is not None
                assert member.read() == f"{result.label}/{folder}".encode()


def test_runner_preserves_multiple_literal_items_without_archiving_lookalikes(tmp_path: Path) -> None:
    outputs = {name: str(tmp_path / f"{name}.tar.gz") for name in ("notes", "photos")}
    cfg = _config(tmp_path, outputs)
    for name, instance in cfg.instances.items():
        instance.with_["items"] = ["tiny.txt", "folder/child.txt"]
        source = tmp_path / "sources" / name
        (source / "folder").mkdir()
        (source / "folder" / "child.txt").write_bytes(f"{name}-child".encode())
        (source / "folder" / "child.txt-copy").write_bytes(b"exclude nested lookalike")
        (source / "tiny.txt-copy").write_bytes(b"exclude root lookalike")

    results = list(Runner(cfg).run(list(cfg.instances.items())))

    assert [result.label for result in results] == list(outputs)
    for result in results:
        assert result.success is True
        with tarfile.open(outputs[result.label], "r:gz") as archive:
            members = {member.name for member in archive.getmembers() if member.isfile()}
            assert members == {"tiny.txt", "folder/child.txt"}
            for path, payload in (("tiny.txt", result.label), ("folder/child.txt", f"{result.label}-child")):
                member = archive.extractfile(path)
                assert member is not None
                assert member.read() == payload.encode()


@pytest.mark.parametrize("message", ["archive storage unavailable", "archive permission denied"])
