    cfg = _config(tmp_path, outputs)
    for instance, engine in zip(cfg.instances.values(), engines, strict=True):
        instance.with_["engine"] = engine
    mocker.patch("backup.capabilities.tar_archive.shutil.which", autospec=True, return_value=None)

    results = list(Runner(cfg).run(list(cfg.instances.items())))

    assert [result.label for result in results] == list(outputs)
    for result, engine in zip(results, engines, strict=True):
        assert result.success is True
        assert ("used python engine" in result.message) is (engine == "system-tar")
        assert result.out_path == outputs[result.label]
        _assert_archive(tmp_path / outputs[result.label], result.label)

def _resolve_settings_class(ctx: click.Context) -> type[GlobalSettings]:
    """Return the settings class registered for the root buvis command."""
    root = ctx.find_root()
    callback = root.command.callback if root.command is not None else None
    if callback is None:
        return GlobalSettings
    return _buvis_callback_settings.get(callback, GlobalSettings)


def _instantiate_settings_or_exit(ctx: click.Context) -> GlobalSettings:
    """Build the settings instance or exit cleanly on configuration errors."""
    settings_class = _resolve_settings_class(ctx)
    try:
        return settings_class()
    except Exception as exc:
        click.echo(f"Configuration error: {exc}", err=True)
        ctx.exit(1)
        raise  # unreachable: ctx.exit raises, but satisfies type checkers


